//! Tests for the JASS handle table (`sim::HandleTable`, docs/spec/handles-2.md).
//!
//! * Behaviour checks written from the spec.
//! * A random operation sequence compared with a small reference model written here.
//! * Operation vectors recorded from the original allocator in Unicorn (`EMU_OPS` and
//!   `EMU_EDGE_OPS`, generated by `tools/emu/handle_vectors.py`; the Unicorn run needs `GAME_DLL`,
//!   the test itself does not).
//! * A JASS script calling demo natives (`CreateTimer`, `DestroyTimer`, `KeepTimer`,
//!   `GetHandleId`) that use the table through the VM extension slot.

use std::collections::BTreeMap;

use jass::compile::compile;
use jass::vm::{NativeRegistry, NativeResult, Value, Vm};
use sim::{HandleTable, HANDLE_BASE};

const BASE: u32 = 0x0010_0000;

#[test]
fn base_is_0x100000() {
    assert_eq!(HANDLE_BASE, 0x0010_0000);
}

#[test]
fn first_id_is_0x100001_after_reset() {
    // Slot 0 is the dummy entry (0x100000 is never handed out), so the first real id is 0x100001.
    let mut t = HandleTable::<u32>::new();
    assert_eq!(t.len(), 1);
    assert_eq!(t.create(7, 1), 0x0010_0001);
    assert_eq!(t.refcount(0x0010_0000), Some(0));
    assert_eq!(t.get(0x0010_0000), None);
}

#[test]
fn sequential_ids() {
    let mut t = HandleTable::new();
    let ids: Vec<u32> = (0..5u32).map(|o| t.create(o, 1)).collect();
    assert_eq!(ids, [0x100001, 0x100002, 0x100003, 0x100004, 0x100005]);
    assert_eq!(t.next_fresh_id(), 0x100006);
    for (o, id) in ids.iter().enumerate() {
        assert_eq!(t.get(*id), Some(&(o as u32)));
        assert_eq!(t.refcount(*id), Some(1));
        assert_eq!(t.flag(*id), Some(1));
        assert_eq!(t.id_of(&(o as u32)), Some(*id));
    }
}

#[test]
fn lifo_reuse_after_several_destroys() {
    let mut t = HandleTable::new();
    let ids: Vec<u32> = (0..5u32).map(|o| t.create(o, 1)).collect();
    // Destroy objects 2, 0, 3 (ids 0x100003, 0x100001, 0x100004), in that order.
    assert!(t.object_died(&2));
    assert!(t.object_died(&0));
    assert!(t.object_died(&3));
    assert_eq!(t.free_ids(), [ids[2], ids[0], ids[3]]);
    // Last freed is first reused.
    assert_eq!(t.create(10, 1), ids[3]);
    assert_eq!(t.create(11, 1), ids[0]);
    assert_eq!(t.create(12, 1), ids[2]);
    // Stack empty again: growth continues from the table length (6 entries before this).
    assert_eq!(t.create(13, 1), 0x100006);
    assert_eq!(t.len(), 7);
}

#[test]
fn add_ref_keeps_id_reserved_after_destroy() {
    let mut t = HandleTable::new();
    let a = t.create(1, 1);
    t.add_ref(a);
    assert_eq!(t.refcount(a), Some(2));
    // Destroying the object drops the creation reference only.
    assert!(t.object_died(&1));
    assert_eq!(t.refcount(a), Some(1));
    assert!(t.free_ids().is_empty());
    // The id is not handed out again, and it no longer names an object.
    assert_eq!(t.get(a), None);
    assert_eq!(t.id_of(&1), None);
    assert_eq!(t.create(2, 1), 0x100002);
    // The last holder lets go: the id is free and is reused next.
    t.release(a);
    assert_eq!(t.free_ids(), [a]);
    assert_eq!(t.create(3, 1), a);
}

#[test]
fn release_frees_only_at_zero() {
    let mut t = HandleTable::new();
    let a = t.create(1, 1);
    t.add_ref(a);
    t.add_ref(a);
    t.release(a);
    t.release(a);
    assert_eq!(t.refcount(a), Some(1));
    assert!(t.free_ids().is_empty());
    assert_eq!(t.get(a), Some(&1));
    t.release(a);
    assert_eq!(t.free_ids(), [a]);
    assert_eq!(t.get(a), None);
    assert_eq!(t.id_of(&1), None);
}

#[test]
fn same_object_gives_same_id() {
    let mut t = HandleTable::new();
    let a = t.create(42, 1);
    let len = t.len();
    // Second registration: same id, no new slot, count unchanged.
    assert_eq!(t.create(42, 1), a);
    assert_eq!(t.create(42, 7), a);
    assert_eq!(t.refcount(a), Some(1));
    assert_eq!(t.flag(a), Some(1));
    assert_eq!(t.len(), len);
    // After the object dies it gets a new id (growth, since the stack is empty).
    assert!(t.object_died(&42));
    assert_eq!(t.free_ids(), [a]);
    assert_eq!(t.create(42, 1), a);
}

#[test]
fn object_died_is_once_only() {
    let mut t = HandleTable::new();
    let a = t.create(5, 1);
    t.add_ref(a);
    assert!(t.object_died(&5));
    // A second death notice does nothing: the creation reference was already released.
    assert!(!t.object_died(&5));
    assert_eq!(t.refcount(a), Some(1));
    assert!(t.free_ids().is_empty());
    // An object whose id was already released to zero has no live id to release.
    let b = t.create(6, 1);
    t.release(b);
    assert!(!t.object_died(&6));
    assert_eq!(t.free_ids(), [b]);
}

#[test]
fn null_ids_are_ignored() {
    let mut t = HandleTable::new();
    let a = t.create(1, 1);
    for null in [0u32, 1, 0x0000_ffff, BASE - 1] {
        assert_eq!(t.get(null), None);
        assert_eq!(t.refcount(null), None);
        assert_eq!(t.flag(null), None);
        t.add_ref(null);
        t.release(null);
    }
    assert_eq!(t.refcount(a), Some(1));
    assert_eq!(t.len(), 2);
    assert!(t.free_ids().is_empty());
}

#[test]
fn reset_restarts_numbering() {
    let mut t = HandleTable::new();
    let a = t.create(1, 1);
    let b = t.create(2, 1);
    t.release(a);
    t.reset();
    assert_eq!(t.len(), 1);
    assert!(t.free_ids().is_empty());
    assert_eq!(t.get(b), None);
    assert_eq!(t.id_of(&2), None);
    assert_eq!(t.refcount(b), None);
    // Old ids are null now; the first id is 0x100001 again.
    t.release(b);
    assert_eq!(t.len(), 1);
    assert_eq!(t.create(2, 1), 0x100001);
}

// ------------------------------------------------------------------------------------------
// Reference model and random sequences
// ------------------------------------------------------------------------------------------

/// Deterministic xorshift64 (no external crates, no system randomness).
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        x
    }

    fn below(&mut self, n: u64) -> u64 {
        self.next() % n
    }
}

#[derive(Clone, Copy)]
struct Slot {
    count: u32,
    object: Option<u32>,
}

/// The reference model: plain maps and vectors, written independently of `HandleTable`. Object to
/// id links are never removed; a link counts only while the id's slot still names the object.
#[derive(Default)]
struct Model {
    /// Every id that has been issued, with its count and object.
    slots: BTreeMap<u32, Slot>,
    /// Released ids, last released on top.
    free: Vec<u32>,
    /// Object to the id it was last given.
    links: BTreeMap<u32, u32>,
}

impl Model {
    /// Dummy slot plus one entry per issued id.
    fn table_len(&self) -> usize {
        1 + self.slots.len()
    }

    /// The id `obj` holds right now, if any.
    fn live(&self, obj: u32) -> Option<u32> {
        let id = *self.links.get(&obj)?;
        (self.slots.get(&id)?.object == Some(obj)).then_some(id)
    }

    fn create(&mut self, obj: u32) -> u32 {
        if let Some(id) = self.live(obj) {
            return id;
        }
        let id = match self.free.pop() {
            Some(id) => id,
            None => BASE + self.table_len() as u32,
        };
        self.slots.insert(
            id,
            Slot {
                count: 1,
                object: Some(obj),
            },
        );
        self.links.insert(obj, id);
        id
    }

    fn add_ref(&mut self, id: u32) {
        if let Some(s) = self.slots.get_mut(&id) {
            s.count = s.count.wrapping_add(1);
        }
    }

    fn release(&mut self, id: u32) {
        if self.slots.contains_key(&id) {
            self.drop_count(id);
        }
    }

    fn drop_count(&mut self, id: u32) {
        let s = self.slots.get_mut(&id).expect("issued id");
        if s.count == 0 {
            return;
        }
        s.count -= 1;
        if s.count == 0 {
            s.object = None;
            self.free.push(id);
        }
    }

    fn object_died(&mut self, obj: u32) -> bool {
        match self.live(obj) {
            Some(id) => {
                self.slots.get_mut(&id).expect("issued id").object = None;
                self.drop_count(id);
                true
            }
            None => false,
        }
    }

    fn reset(&mut self) {
        *self = Model::default();
    }
}

const OBJECTS: u64 = 24;

/// Compares every observable of the table with the model.
fn check_same(t: &HandleTable<u32>, m: &Model, step: usize) {
    assert_eq!(t.len(), m.table_len(), "step {step}: table length");
    assert_eq!(t.free_ids(), m.free.as_slice(), "step {step}: free stack");
    for (&id, s) in &m.slots {
        assert_eq!(
            t.refcount(id),
            Some(s.count),
            "step {step}: count of {id:#x}"
        );
        assert_eq!(
            t.get(id).copied(),
            s.object,
            "step {step}: object of {id:#x}"
        );
    }
    for obj in 0..OBJECTS as u32 {
        assert_eq!(t.id_of(&obj), m.live(obj), "step {step}: id of {obj}");
    }
}

#[test]
fn random_sequences_match_reference_model() {
    for seed in [1u64, 0x9e37_79b9_7f4a_7c15, 0xdead_beef] {
        let mut rng = Rng(seed);
        let mut t = HandleTable::<u32>::new();
        let mut m = Model::default();
        for step in 0..20_000 {
            let r = rng.below(1000);
            if r < 350 {
                let obj = rng.below(OBJECTS) as u32;
                assert_eq!(
                    t.create(obj, 1),
                    m.create(obj),
                    "step {step}: create({obj})"
                );
            } else if r < 800 {
                // add_ref / release on an issued id, now and then on a null id.
                let id = pick_id(&mut rng, &m);
                if r < 500 {
                    t.add_ref(id);
                    m.add_ref(id);
                } else {
                    t.release(id);
                    m.release(id);
                }
            } else if r < 990 {
                let obj = rng.below(OBJECTS) as u32;
                assert_eq!(
                    t.object_died(&obj),
                    m.object_died(obj),
                    "step {step}: death {obj}"
                );
            } else {
                t.reset();
                m.reset();
            }
            check_same(&t, &m, step);
        }
    }
}

/// An issued id most of the time, otherwise a null id (below the base).
fn pick_id(rng: &mut Rng, m: &Model) -> u32 {
    if m.slots.is_empty() || rng.below(10) == 0 {
        return rng.below(BASE as u64) as u32;
    }
    let i = rng.below(m.slots.len() as u64) as usize;
    *m.slots.keys().nth(i).expect("index in range")
}

