#[test]
fn matches_original_allocator_sequence() {
    assert!(
        !EMU_OPS.is_empty() && !EMU_EDGE_OPS.is_empty(),
        "vectors not generated"
    );
    replay_original(EMU_OPS);
    replay_original(EMU_EDGE_OPS);
}

/// Replays recorded operations and checks every returned id and every recorded count and length.
fn replay_original(ops: &[(Op, u32, u32, u32, usize, usize)]) {
    let mut t = HandleTable::<u32>::new();
    for (i, &(op, arg, ret, rc, table_len, free_len)) in ops.iter().enumerate() {
        let touched = match op {
            Op::Create => {
                let id = t.create(arg, 1);
                assert_eq!(id, ret, "op {i}: create({arg})");
                id
            }
            Op::AddRef => {
                t.add_ref(arg);
                arg
            }
            Op::Release => {
                t.release(arg);
                arg
            }
        };
        assert_eq!(
            t.refcount(touched).unwrap_or(0),
            rc,
            "op {i}: count of {touched:#x}"
        );
        assert_eq!(t.len(), table_len, "op {i}: table length");
        assert_eq!(t.free_ids().len(), free_len, "op {i}: free stack length");
    }
}

// ------------------------------------------------------------------------------------------
// JASS natives on the table (the VM extension slot)
// ------------------------------------------------------------------------------------------

/// Host state the demo natives use: the handle table and the object counter.
#[derive(Default)]
struct World {
    handles: HandleTable<u32>,
    next_object: u32,
}

const SCRIPT: &str = r#"
type timer extends handle

native CreateTimer takes nothing returns timer
native DestroyTimer takes timer t returns nothing
native KeepTimer takes timer t returns nothing
native GetHandleId takes handle h returns integer

globals
    integer gA = 0
    integer gB = 0
    integer gC = 0
    integer gD = 0
endglobals

function Demo takes nothing returns nothing
    local timer t1 = null
    local timer t2 = null
    local timer t3 = null
    local timer t4 = null
    set t1 = CreateTimer()
    set t2 = CreateTimer()
    set gA = GetHandleId(t1)
    set gB = GetHandleId(t2)
    call KeepTimer(t1)
    call DestroyTimer(t1)
    call DestroyTimer(t2)
    set t3 = CreateTimer()
    set t4 = CreateTimer()
    set gC = GetHandleId(t3)
    set gD = GetHandleId(t4)
endfunction
"#;

fn demo_registry() -> NativeRegistry {
    let mut r = NativeRegistry::with_builtins();
    r.register("CreateTimer", |ctx, _| {
        let w = ctx.extension::<World>().expect("world inserted");
        w.next_object += 1;
        let obj = w.next_object;
        let id = w.handles.create(obj, 1);
        NativeResult::Return(Value::Handle(id))
    });
    r.register("DestroyTimer", |ctx, a| {
        let w = ctx.extension::<World>().expect("world inserted");
        if let Some(obj) = a[0].as_handle().and_then(|id| w.handles.get(id).cloned()) {
            w.handles.object_died(&obj);
        }
        NativeResult::Return(Value::Null)
    });
    r.register("KeepTimer", |ctx, a| {
        let w = ctx.extension::<World>().expect("world inserted");
        if let Some(id) = a[0].as_handle() {
            w.handles.add_ref(id);
        }
        NativeResult::Return(Value::Null)
    });
    r
}

fn demo_vm() -> Vm {
    let prog = jass::parse(SCRIPT).expect("script parses");
    let module = compile(&[prog]).expect("script compiles");
    let mut vm = Vm::new(module, demo_registry(), None).expect("vm");
    vm.insert_extension(World::default());
    vm
}

fn int_global(vm: &Vm, name: &str) -> i32 {
    vm.global(name)
        .and_then(|v| v.as_integer())
        .unwrap_or_else(|| panic!("integer global {name}"))
}

#[test]
fn script_natives_use_the_table_through_the_vm() {
    let mut vm = demo_vm();
    vm.call("Demo", &[]).expect("Demo runs");

    // GetHandleId is the identity on the handle value.
    assert_eq!(int_global(&vm, "gA"), 0x0010_0001);
    assert_eq!(int_global(&vm, "gB"), 0x0010_0002);
    // t2 was destroyed without a hold, so its id is reused first (LIFO).
    assert_eq!(int_global(&vm, "gC"), 0x0010_0002);
    assert_eq!(int_global(&vm, "gD"), 0x0010_0003);

    let w = vm.extension::<World>().expect("world");
    // t1 is still reserved by KeepTimer: it has no object but count 1.
    assert_eq!(w.handles.refcount(0x0010_0001), Some(1));
    assert_eq!(w.handles.get(0x0010_0001), None);
    assert_eq!(w.handles.get(0x0010_0002), Some(&3));
    assert_eq!(w.handles.get(0x0010_0003), Some(&4));
    assert!(w.handles.free_ids().is_empty());
    assert_eq!(w.handles.len(), 4);
}

#[test]
fn get_handle_id_of_null_is_zero() {
    let src = r#"
native GetHandleId takes handle h returns integer
globals
    integer gN = -1
endglobals
function Null takes nothing returns nothing
    set gN = GetHandleId(null)
endfunction
"#;
    let prog = jass::parse(src).expect("parses");
    let module = compile(&[prog]).expect("compiles");
    let mut vm = Vm::new(module, NativeRegistry::with_builtins(), None).expect("vm");
    vm.call("Null", &[]).expect("runs");
    assert_eq!(int_global(&vm, "gN"), 0);
}
